export function JourneyPortal({ language }) {
  const path = window.location.pathname;
  const page = path.split('/').filter(Boolean);
  if (path === '/programs') return <CatalogPage language={language} />;
  if (page[0] === 'checkout' && page[1] === 'one-to-one-coaching' && !getSession()) return <GuestCoachingCheckout language={language} />;
  return <ProtectedPortal language={language} page={page} />;
}

function GuestCoachingCheckout({ language }) {
  const ar = language === 'ar'; const [sessions, setSessions] = useState(null); const [catalog, setCatalog] = useState(null); const [form, setForm] = useState({ name: '', email: '', sessionId: '' }); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(''); const [error, setError] = useState('');
  useEffect(() => { Promise.all([getAvailableSessions(), getCatalog(language)]).then(([available, products]) => { setSessions(available.filter((item) => item.sessionType === 'coaching')); setCatalog(products); }).catch((e) => setError(e.message)); }, [language]);
  useEffect(() => { const query=new URLSearchParams(window.location.search); if(query.get('payment')!=='meps-guest-return') return; const paymentId=query.get('paymentId'); const resultIndicator=query.get('resultIndicator'); if(!paymentId || !resultIndicator){setError(ar?'لم تُرجع بوابة الدفع نتيجة صالحة.':'The payment gateway did not return a valid result.');return;} setBusy(true); completeGuestMepsPayment(paymentId,resultIndicator,language).then(() => { setMessage(ar?'تم الدفع وتأكيد الجلسة. ستصلك التفاصيل ورابط الاجتماع بالبريد الإلكتروني.':'Payment and booking confirmed. Your meeting details and link will be emailed to you.'); window.history.replaceState({},'', '/checkout/one-to-one-coaching'); }).catch((requestError)=>setError(requestError.response?.data?.message||requestError.message)).finally(()=>setBusy(false)); },[ar,language]);
  const product = catalog?.find((item) => item.slug === 'one-to-one-coaching'); const submit = async (e) => { e.preventDefault(); setBusy(true); setError(''); try { const checkout = await guestCoachingCheckout(form.name, form.email, form.sessionId, language); if(checkout.mode==='meps' && checkout.sessionId && checkout.checkoutScriptUrl){await launchMepsCheckout(checkout.checkoutScriptUrl,checkout.sessionId);return;} throw new Error(ar?'تعذر بدء الدفع عبر MEPS.':'MEPS checkout could not be started.'); } catch (x) { setError(x.response?.data?.message || x.message); setBusy(false); } };
  return <PortalShell language={language}><Grid container spacing={4} maxWidth="lg" mx="auto"><Grid size={{ xs: 12, md: 5 }}><Paper sx={{ p: 4, bgcolor: 'brand.navy', color: 'white', minHeight: 420 }}><CalendarMonthRoundedIcon color="secondary" sx={{ fontSize: 60 }} /><Typography variant="h3" sx={{ color: 'white', mt: 3 }}>{product?.title ?? (ar ? 'جلسة إرشاد مهني' : 'Career Coaching Session')}</Typography><Typography sx={{ mt: 2, color: 'rgba(255,255,255,.7)', lineHeight: 1.8 }}>{product?.summary}</Typography><Typography variant="h3" sx={{ color: 'secondary.main', mt: 5 }}>{product?.price} {product?.currency}</Typography><Typography>{product?.duration}</Typography></Paper></Grid><Grid size={{ xs: 12, md: 7 }}><Paper component="form" onSubmit={submit} sx={{ p: { xs: 3, md: 5 } }}><Typography variant="h3">{ar ? 'اختر موعدك وأكمل الدفع' : 'Choose your time and pay'}</Typography><Typography color="text.secondary" sx={{ mt: 1, mb: 3 }}>{ar ? 'لا تحتاج لإنشاء حساب.' : 'No account is required.'}</Typography>{message && <Alert severity="success" sx={{ mb: 2 }}>{message}</Alert>}{error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}<Stack spacing={2}><TextField required label={ar ? 'الاسم الكامل' : 'Full name'} value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /><TextField required type="email" label={ar ? 'البريد الإلكتروني' : 'Email'} value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} /><TextField required select label={ar ? 'الموعد المتاح' : 'Available time'} value={form.sessionId} onChange={(e) => setForm({ ...form, sessionId: e.target.value })}>{(sessions ?? []).map((session) => <MenuItem key={session.id} value={session.id}>{new Date(session.startsAtUtc).toLocaleString(ar ? 'ar-JO' : 'en-US')} · {ar ? session.titleAr : session.titleEn}</MenuItem>)}</TextField><Alert severity="info">{ar ? 'سيتم استخدام بوابة الدفع المفعلة في بيئة الإنتاج. الوضع الحالي اختبار آمن.' : 'The configured production payment provider will be used. The current environment is safe test mode.'}</Alert><Button type="submit" size="large" variant="contained" disabled={busy || !form.sessionId}>{busy ? <CircularProgress size={22} /> : (ar ? 'ادفع وأكد الجلسة' : 'Pay & confirm session')}</Button></Stack></Paper></Grid></Grid></PortalShell>;
}

function ProtectedPortal({ language, page }) {
  const [snapshot, setSnapshot] = useState(null);
  const [siteContent, setSiteContent] = useState(null);
  const [error, setError] = useState('');
  const copy = text[language];
  useEffect(() => {
    let active = true;

    async function loadPortal() {
      try {
        const [journey, content] = await Promise.all([getJourney(language), getLandingContent(language)]);
        if (!active) return;
        setSnapshot(journey);
        setSiteContent(content);
      } catch (requestError) {
        if (!active) return;
        if (requestError.response?.status === 401) { clearSession(); window.location.href = `/login?returnUrl=${encodeURIComponent(window.location.pathname)}`; }
        else setError(requestError.message);
      }
    }

    loadPortal();
    return () => { active = false; };
  }, [language]);

  if (!getSession()) { window.location.replace(`/login?returnUrl=${encodeURIComponent(window.location.pathname)}`); return null; }
  if ((!snapshot || !siteContent) && !error) return <Loading />;

  let content;
  if (page[0] === 'checkout') content = <CheckoutPage language={language} slug={page[1]} snapshot={snapshot} offer={siteContent.courseOffers?.find((item) => item.slug === page[1])} paymentTerms={siteContent.paymentTerms} onUpdate={setSnapshot} />;
  else if (page[0] === 'learn') content = <LearningPage language={language} slug={page[1]} snapshot={snapshot} offer={siteContent.courseOffers?.find((item) => item.slug === page[1])} onUpdate={setSnapshot} />;
  else if (page[0] === 'booking') content = <BookingPage language={language} onUpdate={setSnapshot} />;
  else if (page[0] === 'assessment') content = <AssessmentPage language={language} assessmentKey={page[1]} snapshot={snapshot} onUpdate={setSnapshot} />;
  else if (page[0] === 'career-profile-print') content = <CareerProfilePrint language={language} snapshot={snapshot} />;
  else content = <BawsalaClientDashboard language={language} snapshot={snapshot} siteContent={siteContent} />;

  return <PortalShell language={language}>{error ? <Alert severity="error">{error}</Alert> : content}</PortalShell>;
}

function PortalShell({ language, children }) {
  const copy = text[language];
  return (
    <Box sx={{ minHeight: '100vh', bgcolor: '#f7f6f1', backgroundImage: 'radial-gradient(circle at 5% 10%,rgba(198,154,85,.07),transparent 28%),radial-gradient(circle at 95% 20%,rgba(16,45,91,.06),transparent 30%)' }}>
      <AppBar position="sticky" elevation={0} sx={{ bgcolor: 'rgba(255,255,255,.92)', color: '#152013', borderBottom: '1px solid #e5e3db', backdropFilter: 'blur(18px)', boxShadow: '0 8px 30px rgba(16,45,91,.045)' }}>
        <Container maxWidth="xl"><Toolbar disableGutters sx={{ gap: 1, minHeight: 82 }}>
          <BrandLogo compact />
          <Box sx={{ flexGrow: 1 }} />
          <Button component="a" href="/dashboard" startIcon={<DashboardRoundedIcon />} sx={{ display: { xs: 'none', md: 'flex' }, px: 2, color: '#102d5b', bgcolor: 'rgba(16,45,91,.07)' }}>{copy.dashboard}</Button>
          <Button component="a" href="/programs" startIcon={<MenuBookRoundedIcon />} sx={{ display: { xs: 'none', md: 'flex' }, px: 2, color: '#3f4941' }}>{copy.programs}</Button>
          <Button component="a" href="/booking" startIcon={<CalendarMonthRoundedIcon />} sx={{ display: { xs: 'none', md: 'flex' }, px: 2, color: '#3f4941' }}>{copy.booking}</Button>
          <Divider orientation="vertical" flexItem sx={{ mx: 1, my: 2.2 }} />
          <Chip label={language === 'ar' ? 'مساحة العميل' : 'Client space'} size="small" sx={{ display: { xs: 'none', sm: 'flex' }, bgcolor: '#f3eadb', color: '#876326', fontWeight: 900 }} />
          <IconButton onClick={() => { clearSession(); window.location.href = '/login'; }} aria-label={copy.logout} sx={{ ml: 1, color: '#102d5b', border: '1px solid #e2e2da' }}><LogoutRoundedIcon /></IconButton>
        </Toolbar></Container>
      </AppBar>
      <Container maxWidth="xl" sx={{ py: { xs: 3, md: 5 } }}>{children}</Container>
    </Box>
  );
}

function CatalogPage({ language }) {
  const [products, setProducts] = useState(null); const [error, setError] = useState(''); const copy = text[language];
  useEffect(() => { getCatalog(language).then(setProducts).catch((e) => setError(e.message)); }, [language]);
  if (!products) return error ? <Alert severity="error">{error}</Alert> : <Loading />;
  return <PortalShell language={language}><SectionHeader eyebrow="Dana programs" title={copy.explore} /><Grid container spacing={3}>{products.map((product) => <Grid key={product.slug} size={{ xs: 12, md: 4 }}><ProductCard product={product} copy={copy} /></Grid>)}</Grid></PortalShell>;
}

function ProductCard({ product, copy }) {
  return <Card sx={{ height: '100%', overflow: 'hidden' }}><Box sx={{ height: 210, bgcolor: product.type === 'cohort' ? 'brand.navy' : product.type === 'coaching' ? 'brand.forest' : '#d8bd74', display: 'grid', placeItems: 'center', color: 'white', backgroundImage: product.coverUrl ? `linear-gradient(180deg, transparent, rgba(8,12,31,.35)), url(${product.coverUrl})` : 'none', backgroundSize: 'cover', backgroundPosition: 'center' }}>{!product.coverUrl && (product.type === 'cohort' ? <AutoAwesomeRoundedIcon sx={{ fontSize: 66 }} /> : product.type === 'coaching' ? <CalendarMonthRoundedIcon sx={{ fontSize: 66 }} /> : <MenuBookRoundedIcon sx={{ fontSize: 66 }} />)}</Box><CardContent sx={{ p: 3 }}><Stack spacing={2}><Chip label={product.duration} sx={{ alignSelf: 'flex-start' }} /><Typography variant="h4" sx={{ fontSize: 27 }}>{product.title}</Typography><Typography color="text.secondary" sx={{ minHeight: 54 }}>{product.summary}</Typography><Divider /><Typography variant="h5" fontWeight={900}>{product.price} {product.currency}</Typography><Button component="a" href={`/checkout/${product.slug}`} variant="contained" fullWidth>{copy.buy}</Button></Stack></CardContent></Card>;
}

function DashboardPage({ language, snapshot, siteContent }) {
  const copy = text[language]; const enrolled = snapshot.state.enrollments;
  const assessmentSequence = ['strengths', 'interests', 'values', 'purpose'];
  const hasCareerClarity = enrolled.some((item) => item.productSlug === 'career-clarity-program');
  const nextAssessmentKey = assessmentSequence.find((key) => !snapshot.state.assessments[key]) ?? 'strengths';
  const careerClarityHref = hasCareerClarity ? `/assessment/${nextAssessmentKey}` : '/checkout/career-clarity-program';
  const clientStories = (siteContent.stories ?? []).filter((story) => story.isVisible && ['client', 'both'].includes(story.audience?.toLowerCase()));
  const courseRows = enrolled.map((entry) => {
    const product = snapshot.catalog.find((item) => item.slug === entry.productSlug);
    if (!product) return null;
    const lessons = product.modules.flatMap((module) => module.lessons);
    const completed = entry.completedLessonIds.length;
    const percent = lessons.length ? Math.min(100, Math.round(completed / lessons.length * 100)) : 0;
    const nextLesson = lessons.find((lesson) => !entry.completedLessonIds.includes(lesson.id));
    return { entry, product, lessons, completed, percent, nextLesson };
  }).filter(Boolean);
  const totalLessons = courseRows.reduce((sum, row) => sum + row.lessons.length, 0);
  const totalCompleted = courseRows.reduce((sum, row) => sum + row.completed, 0);
  const overallProgress = totalLessons ? Math.min(100, Math.round(totalCompleted / totalLessons * 100)) : 0;
  const primaryCourse = courseRows.find((row) => row.percent < 100) ?? courseRows[0];
  const nextBooking = [...snapshot.state.bookings].filter((item) => new Date(item.startsAtUtc) > new Date()).sort((a, b) => new Date(a.startsAtUtc) - new Date(b.startsAtUtc))[0];
  const firstName = snapshot.clientName.split(' ')[0];
  const labels = language === 'ar' ? { greeting: 'مساء مليء بالإنجاز', subtitle: 'كل خطوة صغيرة اليوم تصنع وضوحاً أكبر لمسارك غداً.', journey: 'رحلتك الآن', overall: 'التقدم الكلي', courses: 'دوراتي', completed: 'دروس مكتملة', next: 'أكمل من حيث توقفت', viewAll: 'استكشف البرامج', schedule: 'جلستك القادمة', noSession: 'لا توجد جلسة قادمة بعد', identity: 'بوصلة مسارك', identityHint: 'ملامح هويتك المهنية تتضح مع كل تقييم.', quick: 'خطوات سريعة', assessment: 'أكمل تقييمك', browse: 'تصفح البرامج', book: 'احجز جلسة', enrolled: 'مسجل', lessons: 'درس' } : { greeting: 'Make today count', subtitle: 'Every focused step today creates more clarity for your next chapter.', journey: 'Your journey now', overall: 'Overall progress', courses: 'My courses', completed: 'Lessons completed', next: 'Continue where you left off', viewAll: 'Explore programs', schedule: 'Your next session', noSession: 'No upcoming session yet', identity: 'Your career compass', identityHint: 'Your professional identity gets clearer with every assessment.', quick: 'Quick moves', assessment: 'Continue assessment', browse: 'Browse programs', book: 'Book a session', enrolled: 'Enrolled', lessons: 'lessons' };
  return <Stack spacing={{ xs: 3, md: 4.5 }} sx={{ '@keyframes dashboardRise': { from: { opacity: 0, transform: 'translateY(18px)' }, to: { opacity: 1, transform: 'translateY(0)' } }, '& > *': { animation: 'dashboardRise .65s ease both' }, '& > *:nth-of-type(2)': { animationDelay: '.08s' }, '& > *:nth-of-type(3)': { animationDelay: '.16s' } }}>
    <Paper sx={{ position: 'relative', overflow: 'hidden', border: 0, borderRadius: { xs: 4, md: 6 }, minHeight: { xs: 440, md: 390 }, p: { xs: 3, sm: 4, md: 6 }, color: 'white', background: 'linear-gradient(125deg, #141a3d 0%, #20295b 52%, #314b36 130%)', boxShadow: '0 34px 90px rgba(18,24,56,.28)' }}>
      <Box sx={{ position: 'absolute', width: 440, height: 440, borderRadius: '50%', border: '1px solid rgba(255,255,255,.09)', top: -240, insetInlineEnd: -80 }} /><Box sx={{ position: 'absolute', width: 240, height: 240, borderRadius: '50%', bgcolor: 'rgba(184,207,124,.1)', filter: 'blur(2px)', bottom: -130, insetInlineStart: '38%' }} />
      <Grid container spacing={4} alignItems="center" sx={{ position: 'relative', height: '100%' }}><Grid size={{ xs: 12, md: 8 }}><Stack spacing={2.5} alignItems="flex-start"><Chip icon={<BoltRoundedIcon />} label={labels.greeting} sx={{ bgcolor: 'rgba(184,207,124,.16)', color: '#dff4aa', border: '1px solid rgba(184,207,124,.25)', '& .MuiChip-icon': { color: '#dff4aa' } }} /><Box><Typography sx={{ color: 'rgba(255,255,255,.62)', fontWeight: 800 }}>{copy.welcome}</Typography><Typography variant="h2" sx={{ mt: .5, color: 'white', fontSize: { xs: 42, md: 64 } }}>{firstName}<Box component="span" sx={{ color: 'secondary.main' }}>.</Box></Typography></Box><Typography sx={{ maxWidth: 620, fontSize: { xs: 17, md: 20 }, lineHeight: 1.7, color: 'rgba(255,255,255,.68)' }}>{labels.subtitle}</Typography>{primaryCourse ? <Button component="a" href={primaryCourse.product.type === 'coaching' ? '/booking' : `/learn/${primaryCourse.product.slug}`} variant="contained" color="secondary" size="large" endIcon={<ArrowForwardRoundedIcon />}>{labels.next}</Button> : <Button component="a" href="/programs" variant="contained" color="secondary" size="large">{labels.viewAll}</Button>}</Stack></Grid><Grid size={{ xs: 12, md: 4 }}><Box sx={{ display: 'grid', placeItems: 'center' }}><Box sx={{ position: 'relative', width: 190, height: 190, borderRadius: '50%', display: 'grid', placeItems: 'center', background: `conic-gradient(#b8cf7c ${overallProgress * 3.6}deg, rgba(255,255,255,.1) 0)`, boxShadow: '0 24px 60px rgba(0,0,0,.25)', '&:after': { content: '""', position: 'absolute', inset: 13, borderRadius: '50%', bgcolor: '#20295b' } }}><Box sx={{ position: 'relative', zIndex: 1, textAlign: 'center' }}><Typography variant="h2" sx={{ color: 'white', fontSize: 50 }}>{overallProgress}%</Typography><Typography variant="caption" sx={{ color: 'rgba(255,255,255,.55)', letterSpacing: 1 }}>{labels.overall}</Typography></Box></Box></Box></Grid></Grid>
    </Paper>

    <Grid container spacing={2.5}><Grid size={{ xs: 12, sm: 4 }}><DashboardMetric icon={<MenuBookRoundedIcon />} value={courseRows.length} label={labels.courses} color="#20295b" /></Grid><Grid size={{ xs: 12, sm: 4 }}><DashboardMetric icon={<CheckCircleRoundedIcon />} value={totalCompleted} label={labels.completed} color="#2f4f23" /></Grid><Grid size={{ xs: 12, sm: 4 }}><DashboardMetric icon={<WorkspacePremiumRoundedIcon />} value={`${overallProgress}%`} label={labels.overall} color="#a47d28" /></Grid></Grid>

    {hasCareerClarity ? <Paper sx={{ p: { xs: 3, md: 4 }, borderRadius: 4, background: 'linear-gradient(120deg, rgba(32,41,91,.06), rgba(184,207,124,.18))' }}><Grid container spacing={3} alignItems="center"><Grid size={{ xs: 12, md: 8 }}><Typography color="primary" fontWeight={900}>{language === 'ar' ? 'ملف الوضوح المهني' : 'Career Clarity Profile'}</Typography><Typography variant="h4" fontWeight={900} sx={{ mt: .5 }}>{snapshot.state.profile?.status === 'ready' ? (language === 'ar' ? 'ملفك جاهز 🎉' : 'Your profile is ready 🎉') : snapshot.state.profile?.status === 'in-review' ? (language === 'ar' ? 'قيد مراجعة دانا' : 'Dana is reviewing your profile') : (language === 'ar' ? 'أكمل تقييماتك الأربعة' : 'Complete your four assessments')}</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>{snapshot.state.profile?.adminNotes || (language === 'ar' ? 'سيجمع الملف نقاط قوتك وميولك وقيمك ورسالة غايتك.' : 'Your profile brings together your strengths, interests, values, and purpose.')}</Typography></Grid><Grid size={{ xs: 12, md: 4 }}><Stack spacing={1.2}>{snapshot.state.profile?.status === 'ready' ? <><Button variant="contained" onClick={() => language === 'ar' ? window.location.assign('/career-profile-print') : downloadCareerProfile(language)}>{language === 'ar' ? 'طباعة أو حفظ PDF' : 'Download PDF profile'}</Button><Button component="a" href="/booking" variant="outlined">{language === 'ar' ? 'احجز جلسة 1:1' : 'Book your 1:1 session'}</Button></> : assessmentSequence.map((key, i) => <Button key={key} component="a" href={`/assessment/${key}`} variant={snapshot.state.assessments[key] ? 'outlined' : 'contained'} disabled={i > 0 && !snapshot.state.assessments[assessmentSequence[i - 1]]}>{snapshot.state.assessments[key] ? '✓ ' : `${i + 1}. `}{key}</Button>)}</Stack></Grid></Grid></Paper> : <Paper sx={{ p: { xs: 3, md: 4 }, borderRadius: 4, border: '1px solid', borderColor: 'divider', background: 'linear-gradient(120deg, #fffdf6, rgba(184,207,124,.16))' }}><Grid container spacing={3} alignItems="center"><Grid size={{ xs: 12, md: 8 }}><Typography color="primary" fontWeight={900}>{language === 'ar' ? 'برنامج وضوح المسار المهني' : 'Career Clarity Program'}</Typography><Typography variant="h4" fontWeight={900} sx={{ mt: .5 }}>{language === 'ar' ? 'ابدأ رحلتك بأربع تقييمات موجهة' : 'Start your journey with four guided assessments'}</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>{language === 'ar' ? 'اكتشف نقاط قوتك وميولك وقيمك ورسالة غايتك، ثم راجع ملفك المهني مع دانا.' : 'Discover your strengths, interests, values, and purpose, then review your career profile with Dana.'}</Typography></Grid><Grid size={{ xs: 12, md: 4 }}><Button component="a" href="/checkout/career-clarity-program" variant="contained" size="large" fullWidth>{language === 'ar' ? 'استكشف البرنامج وابدأ' : 'Explore the program & start'}</Button></Grid></Grid></Paper>}

    <Grid container spacing={3} alignItems="stretch"><Grid size={{ xs: 12, lg: 8 }}><Stack spacing={2.5}><Stack direction="row" justifyContent="space-between" alignItems="end"><Box><Typography color="primary" fontWeight={900}>{labels.journey}</Typography><Typography variant="h3" sx={{ mt: .5 }}>{labels.courses}</Typography></Box><Button component="a" href="/programs">{labels.viewAll}</Button></Stack>{courseRows.length ? <Grid container spacing={2.5}>{courseRows.map(({ entry, product, lessons, percent, nextLesson }) => <Grid key={product.slug} size={{ xs: 12, md: 6 }}><Card sx={{ height: '100%', overflow: 'hidden', border: 0, boxShadow: '0 20px 55px rgba(32,41,91,.1)', transition: 'transform .3s ease, box-shadow .3s ease', '&:hover': { transform: 'translateY(-7px)', boxShadow: '0 28px 70px rgba(32,41,91,.17)' } }}><Box sx={{ position: 'relative', height: 190, bgcolor: 'brand.navy', backgroundImage: product.coverUrl ? `linear-gradient(180deg, rgba(12,16,40,.05), rgba(12,16,40,.72)), url(${product.coverUrl})` : 'linear-gradient(135deg, #20295b, #2f4f23)', backgroundSize: 'cover', backgroundPosition: 'center' }}><Chip label={`${percent}%`} sx={{ position: 'absolute', top: 16, insetInlineEnd: 16, bgcolor: 'rgba(255,255,255,.92)', fontWeight: 900 }} /><Box sx={{ position: 'absolute', insetInline: 20, bottom: 18, color: 'white' }}><Typography variant="caption" sx={{ opacity: .7 }}>{labels.enrolled}</Typography><Typography variant="h5" fontWeight={900}>{product.title}</Typography></Box></Box><CardContent sx={{ p: 2.5 }}><Stack spacing={2}><Stack direction="row" justifyContent="space-between"><Typography variant="body2" color="text.secondary">{entry.completedLessonIds.length}/{lessons.length} {labels.lessons}</Typography><Typography variant="body2" fontWeight={900}>{product.duration}</Typography></Stack><LinearProgress variant="determinate" value={percent} sx={{ height: 8, borderRadius: 5, bgcolor: 'rgba(47,79,35,.09)' }} />{nextLesson && <Typography variant="body2" color="text.secondary" noWrap>{labels.next}: <Box component="span" color="text.primary" fontWeight={800}>{nextLesson.title}</Box></Typography>}<Button component="a" href={product.type === 'coaching' ? '/booking' : `/learn/${product.slug}`} variant="contained" fullWidth endIcon={<ArrowForwardRoundedIcon />}>{percent ? copy.continue : language === 'ar' ? 'ابدأ الآن' : 'Start learning'}</Button></Stack></CardContent></Card></Grid>)}</Grid> : <Paper sx={{ p: 5, borderRadius: 4, textAlign: 'center', border: '1px dashed', borderColor: 'divider' }}><MenuBookRoundedIcon color="primary" sx={{ fontSize: 55 }} /><Typography variant="h5" fontWeight={900} sx={{ mt: 2 }}>{copy.noEnrollments}</Typography><Button component="a" href="/programs" variant="contained" sx={{ mt: 2 }}>{copy.explore}</Button></Paper>}</Stack></Grid>
      <Grid size={{ xs: 12, lg: 4 }}><Stack spacing={2.5} sx={{ height: '100%' }}><Paper sx={{ position: 'relative', overflow: 'hidden', p: 3.5, border: 0, bgcolor: 'brand.forest', color: 'white', minHeight: 245, boxShadow: '0 22px 55px rgba(47,79,35,.22)' }}><Box sx={{ position: 'absolute', width: 170, height: 170, borderRadius: '50%', bgcolor: 'rgba(184,207,124,.09)', top: -80, insetInlineEnd: -50 }} /><CalendarMonthRoundedIcon sx={{ color: 'secondary.main', fontSize: 40 }} /><Typography variant="h5" fontWeight={900} sx={{ mt: 2 }}>{labels.schedule}</Typography>{nextBooking ? <Box sx={{ mt: 2 }}><Typography sx={{ fontSize: 20, fontWeight: 900 }}>{nextBooking.sessionType}</Typography><Typography sx={{ mt: .6, color: 'rgba(255,255,255,.65)' }}>{new Date(nextBooking.startsAtUtc).toLocaleString(language === 'ar' ? 'ar-JO' : 'en-US', { dateStyle: 'medium', timeStyle: 'short' })}</Typography></Box> : <Typography sx={{ mt: 2, color: 'rgba(255,255,255,.6)' }}>{labels.noSession}</Typography>}<Button component="a" href="/booking" color="secondary" variant="contained" fullWidth sx={{ mt: 3 }}>{copy.booking}</Button></Paper><Paper sx={{ p: 3.5, border: 0, bgcolor: '#ebe7cc' }}><Typography color="primary" fontWeight={900}>{labels.quick}</Typography><Stack spacing={1} sx={{ mt: 2 }}><Button component="a" href={careerClarityHref} color="inherit" sx={{ justifyContent: 'flex-start', bgcolor: 'rgba(255,255,255,.48)' }} startIcon={<InsightsRoundedIcon />}>{hasCareerClarity ? labels.assessment : (language === 'ar' ? 'ابدأ برنامج وضوح المسار' : 'Start Career Clarity')}</Button><Button component="a" href="/programs" color="inherit" sx={{ justifyContent: 'flex-start', bgcolor: 'rgba(255,255,255,.48)' }} startIcon={<MenuBookRoundedIcon />}>{labels.browse}</Button><Button component="a" href="/booking" color="inherit" sx={{ justifyContent: 'flex-start', bgcolor: 'rgba(255,255,255,.48)' }} startIcon={<CalendarMonthRoundedIcon />}>{labels.book}</Button></Stack></Paper></Stack></Grid>
    </Grid>
    {snapshot.careerIdentity && <Paper sx={{ position: 'relative', overflow: 'hidden', p: { xs: 3, md: 5 }, border: 0, background: 'linear-gradient(120deg, #f2efd9, #fffdf6)' }}><Grid container spacing={3} alignItems="center"><Grid size={{ xs: 12, md: 8 }}><Typography color="primary" fontWeight={900}>{labels.identity}</Typography><Typography variant="h3" sx={{ my: 1.5 }}>{snapshot.careerIdentity.headline}</Typography><Typography color="text.secondary">{labels.identityHint}</Typography></Grid><Grid size={{ xs: 12, md: 4 }}><Stack direction="row" spacing={1} useFlexGap flexWrap="wrap">{snapshot.careerIdentity.suggestedPaths.map((path) => <Chip key={path} label={path} color="primary" variant="outlined" />)}</Stack></Grid></Grid></Paper>}
    {clientStories.length > 0 && <ClientStories stories={clientStories} language={language} />}
  </Stack>;
}

function DashboardMetric({ icon, value, label, color }) {
  return <Paper sx={{ p: 2.5, border: 0, boxShadow: '0 14px 40px rgba(32,41,91,.07)' }}><Stack direction="row" spacing={2} alignItems="center"><Avatar sx={{ width: 52, height: 52, bgcolor: `${color}14`, color }}>{icon}</Avatar><Box><Typography variant="h4" fontWeight={900} sx={{ lineHeight: 1, color }}>{value}</Typography><Typography variant="body2" color="text.secondary" sx={{ mt: .6 }}>{label}</Typography></Box></Stack></Paper>;
}

function ClientStories({ stories, language }) {
  const [activeStory, setActiveStory] = useState(null);
  const sorted = [...stories].sort((left, right) => left.order - right.order);
  return <Paper sx={{ p: { xs: 2.5, md: 4 }, overflow: 'hidden', bgcolor: 'brand.navy', color: 'white' }}>
    <Typography color="secondary.main" fontWeight={900}>{language === 'ar' ? 'مختارات دانا لك' : 'Selected for your journey'}</Typography>
    <Typography variant="h3" sx={{ mt: 1, mb: 3 }}>{language === 'ar' ? 'قصص ونصائح قصيرة' : 'Stories and quick perspectives'}</Typography>
    <Box sx={{ display: 'grid', gridAutoFlow: 'column', gridAutoColumns: { xs: '72%', sm: '38%', md: '24%' }, gap: 2, overflowX: 'auto', pb: 1.5, scrollSnapType: 'x mandatory' }}>
      {sorted.map((story) => <Box component="button" type="button" key={story.key} onClick={() => setActiveStory(story)} sx={{ position: 'relative', p: 0, border: '1px solid rgba(255,255,255,.15)', borderRadius: 3, overflow: 'hidden', aspectRatio: '9/13', scrollSnapAlign: 'start', bgcolor: '#090d22', color: 'white', cursor: 'pointer', textAlign: 'start' }}><Box component="video" src={story.videoUrl} poster={story.posterUrl || undefined} muted playsInline preload="auto" onLoadedData={(event) => { if (!story.posterUrl && event.currentTarget.currentTime === 0) event.currentTarget.currentTime = .35; }} sx={{ width: 1, height: 1, objectFit: 'cover' }} /><Box sx={{ position: 'absolute', inset: 0, background: 'linear-gradient(180deg, transparent 40%, rgba(4,7,19,.9))' }} /><PlayCircleRoundedIcon sx={{ position: 'absolute', top: 14, insetInlineEnd: 14, color: 'secondary.main', fontSize: 38 }} /><Box sx={{ position: 'absolute', insetInline: 16, bottom: 16 }}><Typography fontWeight={900}>{story.title}</Typography><Typography variant="caption" sx={{ color: 'rgba(255,255,255,.65)' }}>{story.caption}</Typography></Box></Box>)}
    </Box>
    <Dialog open={Boolean(activeStory)} onClose={() => setActiveStory(null)} maxWidth="sm" fullWidth PaperProps={{ sx: { bgcolor: '#070a18', overflow: 'hidden', borderRadius: { xs: 0, sm: 4 } } }}>{activeStory && <DialogContent sx={{ p: 0, position: 'relative', aspectRatio: '9/16', maxHeight: '90vh' }}><IconButton onClick={() => setActiveStory(null)} sx={{ position: 'absolute', zIndex: 2, top: 14, insetInlineEnd: 14, color: 'white', bgcolor: 'rgba(0,0,0,.45)' }}><CloseRoundedIcon /></IconButton><Box component="video" src={activeStory.videoUrl} poster={activeStory.posterUrl || undefined} controls autoPlay playsInline sx={{ width: 1, height: 1, objectFit: 'contain' }} /></DialogContent>}</Dialog>
  </Paper>;
}

function CheckoutPage({ language, slug, snapshot, offer, paymentTerms, onUpdate }) {
  const [busy, setBusy] = useState(false); const [done, setDone] = useState(false); const [error, setError] = useState(''); const [acceptedTerms, setAcceptedTerms] = useState(false); const [termsOpen, setTermsOpen] = useState(false); const copy = text[language]; const product = snapshot.catalog.find((item) => item.slug === slug);
  useEffect(() => { const query = new URLSearchParams(window.location.search); if (query.get('payment') !== 'meps-return') return; const paymentId = query.get('paymentId'); const resultIndicator = query.get('resultIndicator'); if (!paymentId || !resultIndicator) { setError(language === 'ar' ? 'لم تُرجع بوابة الدفع نتيجة صالحة.' : 'The payment gateway did not return a valid result.'); return; } setBusy(true); completeMepsPayment(paymentId, resultIndicator, language).then((journey) => { onUpdate(journey); setDone(true); window.history.replaceState({}, '', `/checkout/${slug}`); }).catch((requestError) => setError(requestError.response?.data?.message || requestError.message)).finally(() => setBusy(false)); }, [language, onUpdate, slug]);
  if (!product) return <Alert severity="error">Product not found</Alert>;
  const terms = paymentTerms ?? (language === 'ar' ? { title: 'الشروط والأحكام', body: '', acceptLabel: 'أوافق على الشروط والأحكام', openLabel: 'قراءة الشروط والأحكام', requiredMessage: 'يجب الموافقة على الشروط والأحكام.' } : { title: 'Terms & Conditions', body: '', acceptLabel: 'I agree to the Terms & Conditions', openLabel: 'Read the Terms & Conditions', requiredMessage: 'You must accept the Terms & Conditions.' });
  const submit = async () => { if (!acceptedTerms) { setError(terms.requiredMessage); return; } setBusy(true); setError(''); try { const checkoutSession = await createStripeCheckoutSession(slug, language); if (checkoutSession.mode === 'stripe' && checkoutSession.redirectUrl) { window.location.assign(checkoutSession.redirectUrl); return; } if (checkoutSession.mode === 'meps' && checkoutSession.sessionId && checkoutSession.checkoutScriptUrl) { await launchMepsCheckout(checkoutSession.checkoutScriptUrl, checkoutSession.sessionId); return; } onUpdate(await enroll(slug, language)); setDone(true); } catch (e) { setError(e.response?.data?.message || e.message); setBusy(false); } };
  if (done) return <Paper sx={{ maxWidth: 680, mx: 'auto', p: 5, textAlign: 'center' }}><CheckCircleRoundedIcon color="success" sx={{ fontSize: 70 }} /><Typography variant="h3" sx={{ my: 2 }}>Welcome to {product.title}</Typography><Button component="a" href="/dashboard" variant="contained">{copy.dashboard}</Button></Paper>;
  const checkout = offer ?? { eyebrow: 'Program offer', title: product.title, description: product.summary, imageUrl: '', benefits: [], paymentTitle: copy.checkout, paymentSubtitle: '', fullNameLabel: 'Full name', emailLabel: 'Email', cardLabel: 'Card details', payButtonLabel: copy.confirm, securePaymentText: 'Secure payment' };
  const checkoutBenefits = Array.isArray(checkout.benefits)
    ? checkout.benefits
    : String(checkout.benefits ?? '').split(/\r?\n|\s{2,}|\|/).map((item) => item.trim()).filter(Boolean);
  const introMedia = [...(checkout.sections ?? []).flatMap((section) => section.lessons ?? []), ...(checkout.lessons ?? [])].find((item) => item.key === 'program-intro')?.videoUrl;
  return <Grid container spacing={{ xs: 3, md: 5 }} maxWidth="lg" mx="auto" alignItems="flex-start">
    {slug === 'career-clarity-program' && introMedia && <Grid size={{ xs: 12 }}><ProgramIntroMedia url={introMedia} language={language} /></Grid>}
    <Grid size={{ xs: 12, md: 5 }}><Paper sx={{ overflow: 'hidden', position: { md: 'sticky' }, top: { md: 100 } }}>{checkout.imageUrl ? <Box component="img" src={checkout.imageUrl} alt={checkout.title} sx={{ width: '100%', height: { xs: 240, md: 330 }, objectFit: 'cover', display: 'block' }} /> : <Box sx={{ height: { xs: 220, md: 300 }, display: 'grid', placeItems: 'center', background: 'linear-gradient(145deg,#eef2e9,#f7f0e2)' }}><Box component="img" src="/assets/bawsala-logo.jpg" alt="Bawsala" sx={{ width: 210, maxWidth: '65%', mixBlendMode: 'multiply' }} /></Box>}<Stack spacing={2.2} sx={{ p: { xs: 3, md: 4 } }}><Typography color="primary" fontWeight={900}>{checkout.eyebrow}</Typography><Typography variant="h3" sx={{ fontSize: { xs: 30, md: 40 } }}>{checkout.title}</Typography><Typography color="text.secondary" sx={{ lineHeight: 1.8 }}>{checkout.description}</Typography>{checkoutBenefits.map((benefit) => <Stack key={benefit} direction="row" spacing={1.2} sx={{ alignItems: 'center' }}><CheckCircleRoundedIcon color="primary" fontSize="small" /><Typography>{benefit}</Typography></Stack>)}<Divider /><Stack direction="row" sx={{ justifyContent: 'space-between', alignItems: 'center' }}><Typography fontWeight={800}>{product.duration}</Typography><Typography variant="h4" fontWeight={900}>{product.price} {product.currency}</Typography></Stack></Stack></Paper></Grid>
    <Grid size={{ xs: 12, md: 7 }}><Paper sx={{ p: { xs: 3, md: 5 } }}><Typography variant="h3" sx={{ fontSize: { xs: 30, md: 42 } }}>{checkout.paymentTitle}</Typography><Typography color="text.secondary" sx={{ mt: 1, mb: 3 }}>{checkout.paymentSubtitle}</Typography><Alert severity="info" sx={{ mb: 3 }}>{language === 'ar' ? 'سيتم إدخال بيانات البطاقة في صفحة MEPS الآمنة التابعة لـMastercard. لا يقوم موقع بوصلة بحفظ رقم البطاقة أو رمز CVC.' : 'Your card details are entered on the secure MEPS page powered by Mastercard. Bawsala never stores your card number or CVC.'}</Alert>{error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}<Stack spacing={2.2}><Paper variant="outlined" sx={{ p: 2.5, borderRadius: 2.5 }}><Typography fontWeight={900}>{getSession()?.name}</Typography><Typography color="text.secondary">{getSession()?.email}</Typography></Paper><Paper variant="outlined" sx={{ p: 2, borderRadius: 2.5, bgcolor: acceptedTerms ? 'rgba(47,79,35,.05)' : 'transparent' }}><FormControlLabel control={<Checkbox checked={acceptedTerms} onChange={(event) => { setAcceptedTerms(event.target.checked); setError(''); }} />} label={<Typography variant="body2">{terms.acceptLabel}</Typography>} /><Button size="small" onClick={() => setTermsOpen(true)} sx={{ display: 'block', mx: 4.5 }}>{terms.openLabel}</Button></Paper><Button onClick={submit} disabled={busy} variant="contained" size="large" startIcon={<CreditCardRoundedIcon />} sx={{ minHeight: 58, opacity: acceptedTerms ? 1 : .72 }}>{busy ? <CircularProgress size={22} /> : `${checkout.payButtonLabel} · ${product.price} ${product.currency}`}</Button><Typography variant="body2" textAlign="center" color="text.secondary">🔒 MEPS · Mastercard Payment Gateway Services</Typography></Stack></Paper></Grid>
    <Dialog open={termsOpen} onClose={() => setTermsOpen(false)} maxWidth="sm" fullWidth><DialogContent sx={{ p: { xs: 3, md: 4 } }}><Typography variant="h4" fontWeight={900}>{terms.title}</Typography><Typography color="text.secondary" sx={{ mt: 2, lineHeight: 1.9, whiteSpace: 'pre-line' }}>{terms.body}</Typography><Divider sx={{ my: 3 }} /><Button fullWidth variant="contained" onClick={() => { setAcceptedTerms(true); setTermsOpen(false); setError(''); }}>{terms.acceptLabel}</Button></DialogContent></Dialog>
  </Grid>;
}

function ProgramIntroMedia({ url, language }) {
  const isImage = /\.(png|jpe?g|webp|gif|svg)(\?|$)/i.test(url);
  const media = isImage
    ? <Box component="img" src={url} alt={language === 'ar' ? 'مقدمة برنامج وضوح المسار' : 'Career Clarity introduction'} sx={{ width: 1, maxHeight: 520, objectFit: 'cover', display: 'block' }} />
    : isDirectVideo(url)
      ? <Box component="video" src={url} controls playsInline preload="metadata" sx={{ width: 1, maxHeight: 560, display: 'block', bgcolor: '#080d20' }} />
      : <Box component="iframe" src={toEmbedUrl(url)} title="Career Clarity introduction" allow="autoplay; encrypted-media; picture-in-picture" allowFullScreen sx={{ width: 1, aspectRatio: '16/9', border: 0, display: 'block' }} />;
  return <Paper sx={{ overflow: 'hidden', borderRadius: 4, boxShadow: '0 24px 70px rgba(32,41,91,.13)' }}><Box sx={{ px: { xs: 3, md: 4 }, py: 2.5, color: 'white', background: 'linear-gradient(110deg,#20295b,#2f4f23)' }}><Typography variant="overline" sx={{ color: '#d8bd74', fontWeight: 900 }}>{language === 'ar' ? 'رسالة ترحيبية من دانا' : 'A welcome from Dana'}</Typography><Typography variant="h4" sx={{ color: 'white', mt: .3 }}>{language === 'ar' ? 'ابدأ رحلتك بوضوح' : 'Begin your Career Clarity journey'}</Typography></Box>{media}</Paper>;
}

function launchMepsCheckout(scriptUrl, sessionId) {
  return new Promise((resolve, reject) => {
    const start = () => { try { window.Checkout.configure({ session: { id: sessionId } }); window.Checkout.showPaymentPage(); resolve(); } catch (error) { reject(error); } };
    if (window.Checkout) { start(); return; }
    const script = document.createElement('script'); script.src = scriptUrl; script.async = true; script.dataset.error = 'Payment gateway could not be loaded'; script.onload = start; script.onerror = () => reject(new Error('MEPS payment gateway could not be loaded')); document.head.appendChild(script);
  });
}

function LearningPage({ language, slug, snapshot, offer, onUpdate }) {
  const copy = text[language]; const product = snapshot.catalog.find((item) => item.slug === slug); const enrollment = snapshot.state.enrollments.find((item) => item.productSlug === slug);
  const allLessons = product?.modules.flatMap((module, moduleIndex) => module.lessons.map((lesson) => ({ ...lesson, moduleTitle: module.title, moduleIndex }))) ?? [];
  const [activeLessonId, setActiveLessonId] = useState(allLessons[0]?.id ?? '');
  const [completing, setCompleting] = useState(false);
  const activeIndex = Math.max(0, allLessons.findIndex((lesson) => lesson.id === activeLessonId));
  const activeLesson = allLessons[activeIndex];
  const completedCount = enrollment?.completedLessonIds.length ?? 0;
  const progress = allLessons.length ? Math.min(100, Math.round(completedCount / allLessons.length * 100)) : 0;
  if (!product || !enrollment) return <Alert severity="warning">Enroll in this program first.</Alert>;
  const actionUrl = (lesson) => lesson.type === 'assessment' ? `/assessment/${lesson.id.split('-')[0]}` : lesson.type === 'booking' ? '/booking' : null;
  const move = (offset) => setActiveLessonId(allLessons[activeIndex + offset]?.id ?? activeLesson.id);
  const markComplete = async () => { if (!activeLesson || enrollment.completedLessonIds.includes(activeLesson.id)) return; setCompleting(true); try { onUpdate(await completeLesson(activeLesson.id, language)); } finally { setCompleting(false); } };
  if (!activeLesson) return <Alert severity="info">This course does not have lessons yet.</Alert>;
  return <Box sx={{ mx: { xs: -2, md: -3 }, mt: { xs: -4, md: -6 } }}>
    <Box sx={{ bgcolor: '#11162f', color: 'white', px: { xs: 2, md: 4 }, py: 2 }}><Stack direction="row" spacing={2} alignItems="center"><Button component="a" href="/dashboard" color="secondary" startIcon={<ArrowBackRoundedIcon />}>{copy.back}</Button><Divider orientation="vertical" flexItem sx={{ borderColor: 'rgba(255,255,255,.16)' }} /><Box sx={{ minWidth: 0 }}><Typography fontWeight={900} noWrap>{product.title}</Typography><Typography variant="caption" sx={{ color: 'rgba(255,255,255,.55)' }}>{activeLesson.moduleTitle}</Typography></Box><Box sx={{ flexGrow: 1 }} /><Chip label={`${progress}% ${language === 'ar' ? 'مكتمل' : 'complete'}`} color="secondary" variant="outlined" /></Stack></Box>
    <Grid container sx={{ minHeight: 'calc(100vh - 152px)', bgcolor: '#0a0d1d' }}>
      <Grid size={{ xs: 12, lg: 8.5 }}>
        <Box sx={{ minHeight: { xs: 260, md: 560 }, display: 'grid', placeItems: 'center', bgcolor: '#050713' }}>
          {activeLesson.contentUrl ? <Box key={activeLesson.id} component="video" src={activeLesson.contentUrl} controls controlsList="nodownload" autoPlay playsInline preload="metadata" sx={{ width: '100%', maxHeight: '72vh', aspectRatio: '16/9', display: 'block' }} /> : <Stack alignItems="center" spacing={2} sx={{ color: 'rgba(255,255,255,.6)' }}><PlayCircleRoundedIcon sx={{ fontSize: 84 }} /><Typography>{language === 'ar' ? 'سيتم إضافة فيديو هذا الدرس قريباً' : 'This lesson video is coming soon'}</Typography></Stack>}
        </Box>
        <Box sx={{ bgcolor: 'background.paper', p: { xs: 2.5, md: 4 } }}>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ sm: 'center' }}><Box sx={{ flexGrow: 1 }}><Typography color="primary" fontWeight={900}>{activeLesson.moduleTitle}</Typography><Typography variant="h4" fontWeight={900} sx={{ mt: .7 }}>{activeLesson.title}</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>{activeLesson.durationMinutes} {language === 'ar' ? 'دقيقة' : 'minutes'}</Typography></Box><Button disabled={completing || enrollment.completedLessonIds.includes(activeLesson.id)} onClick={markComplete} variant="contained" startIcon={completing ? <CircularProgress size={18} color="inherit" /> : <CheckCircleRoundedIcon />}>{enrollment.completedLessonIds.includes(activeLesson.id) ? copy.completed : copy.complete}</Button></Stack>
          <Divider sx={{ my: 3 }} />
          <Stack direction="row" justifyContent="space-between"><Button disabled={activeIndex === 0} onClick={() => move(-1)} startIcon={language === 'ar' ? <KeyboardArrowRightRoundedIcon /> : <KeyboardArrowLeftRoundedIcon />}>{language === 'ar' ? 'السابق' : 'Previous'}</Button>{actionUrl(activeLesson) ? <Button component="a" href={actionUrl(activeLesson)} variant="contained">{activeLesson.type === 'booking' ? copy.book : copy.assessment}</Button> : <Button disabled={activeIndex === allLessons.length - 1} onClick={() => move(1)} endIcon={language === 'ar' ? <KeyboardArrowLeftRoundedIcon /> : <KeyboardArrowRightRoundedIcon />}>{language === 'ar' ? 'التالي' : 'Next lesson'}</Button>}</Stack>
        </Box>
      </Grid>
      <Grid size={{ xs: 12, lg: 3.5 }} sx={{ bgcolor: '#f8f8f5', borderInlineStart: '1px solid rgba(0,0,0,.1)', maxHeight: { lg: 'calc(100vh - 152px)' }, overflowY: { lg: 'auto' } }}>
        <Box sx={{ p: 2.5, position: 'sticky', top: 0, bgcolor: '#f8f8f5', zIndex: 2, borderBottom: '1px solid', borderColor: 'divider' }}><Stack direction="row" justifyContent="space-between"><Typography variant="h6" fontWeight={900}>{language === 'ar' ? 'محتوى الدورة' : 'Course content'}</Typography><Typography variant="body2" color="text.secondary">{completedCount}/{allLessons.length}</Typography></Stack><LinearProgress variant="determinate" value={progress} sx={{ mt: 1.5, height: 7, borderRadius: 5 }} /></Box>
        {product.modules.map((module, moduleIndex) => { const moduleDone = module.lessons.filter((lesson) => enrollment.completedLessonIds.includes(lesson.id)).length; return <Accordion key={module.key} defaultExpanded={moduleIndex === activeLesson.moduleIndex} disableGutters elevation={0} sx={{ bgcolor: 'transparent', borderBottom: '1px solid', borderColor: 'divider', '&:before': { display: 'none' } }}><AccordionSummary expandIcon={<ExpandMoreRoundedIcon />} sx={{ py: 1 }}><Box><Typography fontWeight={900}>{module.title}</Typography><Typography variant="caption" color="text.secondary">{moduleDone}/{module.lessons.length} · {module.lessons.reduce((sum, lesson) => sum + lesson.durationMinutes, 0)} min</Typography></Box></AccordionSummary><AccordionDetails sx={{ p: 0 }}>{module.lessons.map((lesson, lessonIndex) => { const completed = enrollment.completedLessonIds.includes(lesson.id); const selected = lesson.id === activeLesson.id; return <Stack component="button" type="button" onClick={() => setActiveLessonId(lesson.id)} key={lesson.id} direction="row" spacing={1.5} alignItems="flex-start" sx={{ width: '100%', p: 2, border: 0, borderTop: '1px solid', borderColor: 'divider', bgcolor: selected ? 'rgba(47,79,35,.1)' : 'transparent', textAlign: 'start', cursor: 'pointer', '&:hover': { bgcolor: 'rgba(47,79,35,.06)' } }}><Box sx={{ pt: .2, color: completed ? 'primary.main' : 'text.secondary' }}>{completed ? <CheckCircleRoundedIcon fontSize="small" /> : <PlayCircleRoundedIcon fontSize="small" />}</Box><Box sx={{ minWidth: 0 }}><Typography variant="body2" fontWeight={selected ? 900 : 700}>{lessonIndex + 1}. {lesson.title}</Typography><Typography variant="caption" color="text.secondary">{lesson.durationMinutes} min</Typography></Box></Stack>; })}</AccordionDetails></Accordion>; })}
      </Grid>
    </Grid>
  </Box>;
}

function BookingPage({ language, onUpdate }) {
  const copy = text[language]; const [sessions, setSessions] = useState(null); const [busyId, setBusyId] = useState(''); const [done, setDone] = useState(false); const [error, setError] = useState('');
  useEffect(() => { getAvailableSessions().then(setSessions).catch((e) => setError(e.message)); }, []);
  const submit = async (sessionId) => { setBusyId(sessionId); setError(''); try { onUpdate(await bookAvailableSession(sessionId, language)); setDone(true); setSessions((current) => current.filter((item) => item.id !== sessionId)); } catch (e) { setError(e.message); } finally { setBusyId(''); } };
  const labels = language === 'ar' ? { eyebrow: 'جلسات دانا', title: 'اختر جلستك القادمة', subtitle: 'احجز من الأوقات المتاحة وانضم إلى جلسة مصممة لدعم خطوتك المهنية التالية.', seats: 'مقاعد متبقية', full: 'مكتملة', empty: 'لا توجد جلسات متاحة حالياً. ستظهر الجلسات الجديدة هنا فور إضافتها.', join: 'احجز هذه الجلسة' } : { eyebrow: 'Sessions with Dana', title: 'Choose your next session', subtitle: 'Book an available time designed to support your next focused career move.', seats: 'seats left', full: 'Full', empty: 'No sessions are available right now. New sessions will appear here as soon as they are published.', join: 'Book this session' };
  if (!sessions && !error) return <Loading />;
  return <Stack spacing={4}><Box><Typography color="primary" fontWeight={900}>{labels.eyebrow}</Typography><Typography variant="h2" sx={{ mt: 1 }}>{labels.title}</Typography><Typography color="text.secondary" sx={{ mt: 1.5, maxWidth: 680, fontSize: 18 }}>{labels.subtitle}</Typography></Box>{done && <Alert severity="success">{copy.confirmed}</Alert>}{error && <Alert severity="error">{error}</Alert>}{sessions?.length ? <Grid container spacing={2.5}>{sessions.map((session) => { const remaining = session.capacity == null ? null : session.capacity - session.attendees.length; const full = remaining !== null && remaining <= 0; return <Grid key={session.id} size={{ xs: 12, md: 6, lg: 4 }}><Card sx={{ height: '100%', border: 0, overflow: 'hidden', boxShadow: '0 20px 55px rgba(32,41,91,.11)' }}><Box sx={{ p: 3, color: 'white', background: 'linear-gradient(135deg, #20295b, #2f4f23)' }}><Stack direction="row" justifyContent="space-between"><Chip label={session.sessionType} color="secondary" size="small" /><CalendarMonthRoundedIcon /></Stack><Typography variant="h5" fontWeight={900} sx={{ mt: 4 }}>{language === 'ar' ? session.titleAr : session.titleEn}</Typography></Box><CardContent sx={{ p: 3 }}><Stack spacing={2}><Box><Typography variant="h4" fontWeight={900}>{new Date(session.startsAtUtc).toLocaleDateString(language === 'ar' ? 'ar-JO' : 'en-US', { day: '2-digit', month: 'short' })}</Typography><Typography color="text.secondary">{new Date(session.startsAtUtc).toLocaleTimeString(language === 'ar' ? 'ar-JO' : 'en-US', { hour: '2-digit', minute: '2-digit' })} – {new Date(session.endsAtUtc).toLocaleTimeString(language === 'ar' ? 'ar-JO' : 'en-US', { hour: '2-digit', minute: '2-digit' })}</Typography></Box><Divider /><Typography fontWeight={800} color={full ? 'error' : 'primary'}>{full ? labels.full : remaining === null ? 'Open capacity' : `${remaining} ${labels.seats}`}</Typography><Button disabled={full || busyId === session.id} onClick={() => submit(session.id)} variant="contained" fullWidth>{busyId === session.id ? <CircularProgress size={20} color="inherit" /> : labels.join}</Button></Stack></CardContent></Card></Grid>; })}</Grid> : <Paper sx={{ p: 6, textAlign: 'center', border: '1px dashed', borderColor: 'divider' }}><CalendarMonthRoundedIcon color="primary" sx={{ fontSize: 60 }} /><Typography color="text.secondary" sx={{ mt: 2 }}>{labels.empty}</Typography></Paper>}</Stack>;
}

const STRENGTHS = ['Creativity','Curiosity','Judgment','Love of learning','Perspective','Bravery','Perseverance','Honesty','Zest','Love','Kindness','Social intelligence','Teamwork','Fairness','Leadership','Forgiveness','Humility','Prudence','Self-regulation','Appreciation of beauty','Gratitude','Hope','Humor','Spirituality'];
const VALUES = ['Achievement','Adventure','Authenticity','Autonomy','Balance','Beauty','Belonging','Challenge','Collaboration','Community','Compassion','Competence','Contribution','Creativity','Curiosity','Dignity','Discipline','Diversity','Excellence','Fairness','Faith','Family','Freedom','Friendship','Growth','Health','Honesty','Impact','Independence','Innovation','Integrity','Joy','Justice','Knowledge','Leadership','Learning','Loyalty','Meaning','Openness','Peace','Purpose','Recognition','Respect','Responsibility','Security','Service','Simplicity','Stability','Success','Teamwork','Trust','Wealth','Wisdom','Wellbeing'];
const RIASEC = { Realistic: 'I enjoy practical, hands-on work', Investigative: 'I enjoy analysing and solving complex questions', Artistic: 'I enjoy creating and expressing original ideas', Social: 'I enjoy helping, teaching, and supporting people', Enterprising: 'I enjoy leading, persuading, and building opportunities', Conventional: 'I enjoy organising information and structured work' };

function LegacyAssessmentPage({ language, assessmentKey, snapshot, onUpdate }) {
  const copy = text[language]; const ar = language === 'ar'; const sequence = ['strengths', 'interests', 'values', 'purpose']; const index = sequence.indexOf(assessmentKey);
  const locked = index > 0 && !snapshot.state.assessments[sequence[index - 1]]; const existing = snapshot.state.assessments[assessmentKey]?.answers ?? {};
  const [selected, setSelected] = useState(Object.values(existing)); const [scores, setScores] = useState({}); const [purpose, setPurpose] = useState(existing.statement ?? ''); const [done, setDone] = useState(false); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const names = ar ? { strengths: 'نقاط القوة الشخصية', interests: 'الميول المهنية RIASEC', values: 'القيم المهنية', purpose: 'رسالة الغاية' } : { strengths: 'Character Strengths', interests: 'RIASEC Career Interests', values: 'Career Values', purpose: 'Purpose Statement' };
  const toggle = (value, limit) => setSelected((items) => items.includes(value) ? items.filter((item) => item !== value) : items.length < limit ? [...items, value] : items);
  const submit = async () => { setBusy(true); setError(''); try { let answers = {}; if (assessmentKey === 'strengths') answers = Object.fromEntries(selected.map((value, i) => [`strength${i + 1}`, value])); else if (assessmentKey === 'values') answers = Object.fromEntries(selected.map((value, i) => [`value${i + 1}`, value])); else if (assessmentKey === 'purpose') answers = { statement: purpose }; else { const totals = Object.keys(RIASEC).map((type) => [type, Array.from({ length: 12 }, (_, i) => Number(scores[`${type}-${i}`] ?? 3)).reduce((a, b) => a + b, 0)]).sort((a, b) => b[1] - a[1]).slice(0, 3); answers = Object.fromEntries(totals.map(([type, score], i) => [`interest${i + 1}`, `${type} (${score}/60)`])); } onUpdate(await saveAssessment(assessmentKey, answers, language)); setDone(true); } catch (e) { setError(e.response?.data?.message || e.message); } finally { setBusy(false); } };
  if (locked) return <Paper sx={{ maxWidth: 760, mx: 'auto', p: 5, textAlign: 'center' }}><Typography variant="h3">🔒</Typography><Typography variant="h5" fontWeight={900} sx={{ mt: 2 }}>{ar ? 'أكمل التقييم السابق أولاً' : 'Complete the previous assessment first'}</Typography><Button component="a" href={`/assessment/${sequence[index - 1]}`} variant="contained" sx={{ mt: 3 }}>{ar ? 'العودة للتقييم السابق' : 'Go to previous assessment'}</Button></Paper>;
  const required = assessmentKey === 'strengths' || assessmentKey === 'values' ? 5 : assessmentKey === 'purpose' ? 1 : 72;
  const progress = assessmentKey === 'interests' ? Object.keys(scores).length : assessmentKey === 'purpose' ? (purpose.trim() ? 1 : 0) : selected.length;
  return <Paper sx={{ maxWidth: 980, mx: 'auto', p: { xs: 3, md: 5 }, borderRadius: 4 }}><Typography color="primary" fontWeight={900}>{ar ? `التقييم ${index + 1} من 4` : `Assessment ${index + 1} of 4`}</Typography><Typography variant="h3" sx={{ mt: 1 }}>{names[assessmentKey] || assessmentKey}</Typography><Typography color="text.secondary" sx={{ mt: 1, mb: 3 }}>{assessmentKey === 'interests' ? (ar ? 'أجب عن 72 عبارة، وسيحسب النظام أعلى ثلاثة ميول تلقائياً.' : 'Rate all 72 statements. Your top three interest areas are calculated automatically.') : assessmentKey === 'purpose' ? (ar ? 'اكتب بياناً واضحاً يلخص الأثر الذي تريد صنعه.' : 'Write a clear statement describing the impact you want to create.') : `${ar ? 'اختر' : 'Select'} ${required}`}</Typography><LinearProgress variant="determinate" value={Math.min(100, progress / required * 100)} sx={{ height: 9, borderRadius: 5, mb: 3 }} />{done && <Alert severity="success" sx={{ mb: 3 }}>{ar ? 'تم الحفظ بنجاح. يمكنك الانتقال للخطوة التالية.' : 'Saved successfully. You can continue to the next step.'}</Alert>}{error && <Alert severity="error" sx={{ mb: 3 }}>{error}</Alert>}
    {(assessmentKey === 'strengths' || assessmentKey === 'values') && <Grid container spacing={1.2}>{(assessmentKey === 'strengths' ? STRENGTHS : VALUES).map((item) => <Grid key={item} size={{ xs: 12, sm: 6, md: 4 }}><Paper variant="outlined" onClick={() => toggle(item, 5)} sx={{ p: 1.8, cursor: 'pointer', borderColor: selected.includes(item) ? 'primary.main' : 'divider', bgcolor: selected.includes(item) ? 'rgba(47,79,35,.08)' : 'white' }}><Stack direction="row" alignItems="center"><Checkbox checked={selected.includes(item)} /><Typography fontWeight={selected.includes(item) ? 900 : 600}>{item}</Typography></Stack></Paper></Grid>)}</Grid>}
    {assessmentKey === 'interests' && <Stack spacing={3}>{Object.entries(RIASEC).map(([type, statement]) => <Box key={type}><Typography variant="h6" fontWeight={900} color="primary">{type}</Typography><Grid container spacing={1.2} sx={{ mt: .5 }}>{Array.from({ length: 12 }, (_, i) => <Grid key={i} size={{ xs: 12, md: 6 }}><TextField select fullWidth size="small" label={`${i + 1}. ${statement}`} value={scores[`${type}-${i}`] ?? ''} onChange={(e) => setScores({ ...scores, [`${type}-${i}`]: e.target.value })}>{[1,2,3,4,5].map((n) => <MenuItem key={n} value={n}>{n} — {n === 1 ? 'Not like me' : n === 5 ? 'Very much like me' : 'Sometimes'}</MenuItem>)}</TextField></Grid>)}</Grid></Box>)}</Stack>}
    {assessmentKey === 'purpose' && <TextField fullWidth multiline minRows={8} label={ar ? 'بيان الغاية الخاص بك' : 'My purpose statement'} value={purpose} onChange={(e) => setPurpose(e.target.value)} placeholder={ar ? 'أستخدم نقاط قوتي في... لخدمة... وصناعة...' : 'I use my strengths in… to serve… and create…'} />}
    <Stack direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" alignItems="center" spacing={2} sx={{ mt: 4 }}><Typography fontWeight={900}>{progress}/{required} {ar ? 'مكتمل' : 'complete'}</Typography><Button disabled={busy || progress < required} onClick={submit} variant="contained" size="large">{busy ? <CircularProgress size={22} color="inherit" /> : copy.save}</Button></Stack>
  </Paper>;
}

function CareerProfilePrint({ language, snapshot }) {
  const ar=language==='ar'; if(snapshot.state.profile?.status!=='ready' || !snapshot.careerIdentity) return <Alert severity="warning">{ar?'ملفك غير جاهز بعد.':'Your profile is not ready yet.'}</Alert>; const identity=snapshot.careerIdentity;
  const rows=[[ar?'نقاط القوة':'Strengths',identity.strengths],[ar?'الميول المهنية':'Career interests',identity.interests],[ar?'القيم':'Values',identity.values],[ar?'الغاية':'Purpose',identity.purpose]];
  return <Box dir={ar?'rtl':'ltr'} sx={{ maxWidth:850,mx:'auto','@media print':{position:'fixed',inset:0,bgcolor:'white',zIndex:9999,p:0,'button,a':{display:'none'}} }}><Paper sx={{ p:{xs:3,md:7},borderRadius:4 }}><Stack direction="row" justifyContent="space-between" alignItems="center"><BrandLogo/><Button variant="contained" onClick={()=>window.print()}>{ar?'طباعة / حفظ PDF':'Print / Save PDF'}</Button></Stack><Divider sx={{my:4}}/><Typography color="primary" fontWeight={900}>{ar?'ملف الوضوح المهني':'CAREER CLARITY PROFILE'}</Typography><Typography variant="h2" sx={{mt:1}}>{snapshot.clientName}</Typography><Typography color="text.secondary" sx={{mt:1}}>{identity.headline}</Typography><Stack spacing={2.5} sx={{mt:5}}>{rows.map(([label,value])=><Paper key={label} variant="outlined" sx={{p:3,borderInlineStart:'5px solid',borderColor:'primary.main'}}><Typography color="primary" fontWeight={900}>{label}</Typography><Typography variant="h6" sx={{mt:1,lineHeight:1.8}}>{value}</Typography></Paper>)}</Stack>{snapshot.state.profile.adminNotes&&<Paper sx={{p:3,mt:3,bgcolor:'rgba(184,207,124,.18)'}}><Typography fontWeight={900}>{ar?'ملاحظات دانا':'Dana’s notes'}</Typography><Typography sx={{mt:1,lineHeight:1.8}}>{snapshot.state.profile.adminNotes}</Typography></Paper>}<Divider sx={{my:4}}/><Typography variant="caption" color="text.secondary">Bawsala · {new Date().toLocaleDateString(ar?'ar-JO':'en-US')}</Typography></Paper></Box>;
}

function SectionHeader({ eyebrow, title }) { return <Box><Typography color="primary" fontWeight={900}>{eyebrow}</Typography><Typography variant="h2" sx={{ mt: 1 }}>{title}</Typography></Box>; }
function Loading() { return <Box sx={{ minHeight: '70vh', display: 'grid', placeItems: 'center' }}><CircularProgress /></Box>; }
